import os
import sys


# Formal runs checkpoint their linked worktree and require it to remain Git-clean.
# Keep generated bytecode out of both the primary process and every child process.
os.environ["PYTHONDONTWRITEBYTECODE"] = "1"
sys.dont_write_bytecode = True

from audit_core.orchestrator import main


if __name__ == "__main__":
    raise SystemExit(main())
